namespace CourseCatalog.Services;

using CourseCatalog.Models;

public class CatalogService
{
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Elena Rodriguez", Title = "Professor of Computer Science", Email = "erodriguez@university.edu", Department = "Computer Science", Bio = "Dr. Rodriguez specializes in distributed systems and cloud computing. She has published over 40 peer-reviewed papers and previously worked at Microsoft Research. She received her Ph.D. from MIT." },
            new() { Id = 2, Name = "Dr. James Chen", Title = "Associate Professor of Mathematics", Email = "jchen@university.edu", Department = "Mathematics", Bio = "Dr. Chen is an expert in applied mathematics and numerical analysis. He has received multiple NSF grants for his work on computational modeling and teaches both undergraduate and graduate courses." },
            new() { Id = 3, Name = "Dr. Sarah Thompson", Title = "Professor of English", Email = "sthompson@university.edu", Department = "English", Bio = "Dr. Thompson is an award-winning author and scholar of contemporary American literature. She has published three novels and a collection of critical essays on postmodern fiction." },
            new() { Id = 4, Name = "Dr. Michael Okafor", Title = "Assistant Professor of Physics", Email = "mokafor@university.edu", Department = "Physics", Bio = "Dr. Okafor researches quantum materials and condensed matter physics. He completed postdoctoral work at CERN and brings real-world experimental physics experience to the classroom." },
            new() { Id = 5, Name = "Dr. Lisa Park", Title = "Professor of History", Email = "lpark@university.edu", Department = "History", Bio = "Dr. Park is a historian of East Asian studies with a focus on modern Korean history. She has authored two books and regularly contributes to historical journals and public media." },
            new() { Id = 6, Name = "Dr. David Nguyen", Title = "Associate Professor of Computer Science", Email = "dnguyen@university.edu", Department = "Computer Science", Bio = "Dr. Nguyen focuses on artificial intelligence and machine learning. Before academia, he spent eight years as a senior engineer at Google working on natural language processing systems." },
            new() { Id = 7, Name = "Dr. Maria Santos", Title = "Professor of Biology", Email = "msantos@university.edu", Department = "Biology", Bio = "Dr. Santos is a molecular biologist specializing in genetics and genomics. Her lab has made significant contributions to understanding gene regulation in cancer cells." },
            new() { Id = 8, Name = "Dr. Robert Kim", Title = "Associate Professor of Chemistry", Email = "rkim@university.edu", Department = "Chemistry", Bio = "Dr. Kim's research focuses on organic chemistry and sustainable materials. He holds several patents for biodegradable polymers and has been recognized with the ACS Young Investigator Award." },
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to computer science covering computational thinking, basic programming in Python, data representation, and an overview of how computers work. No prior experience required.", Credits = 3, Department = "Computer Science", Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", Instructor = _instructors[0], IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (sorting, searching, dynamic programming). Emphasizes analysis of time and space complexity.", Credits = 4, Department = "Computer Science", Schedule = "Tue/Thu 10:30 AM–12:00 PM", Location = "Science Hall 305", Instructor = _instructors[0], MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 3, Code = "CS 310", Title = "Artificial Intelligence", Description = "Foundations of AI including search algorithms, knowledge representation, machine learning basics, neural networks, and natural language processing. Includes hands-on projects using Python and TensorFlow.", Credits = 3, Department = "Computer Science", Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Tech Center 110", Instructor = _instructors[5], IsFeatured = true, MaxEnrollment = 45, CurrentEnrollment = 44 },
            new() { Id = 4, Code = "CS 415", Title = "Cloud Computing", Description = "Architecture and design of cloud-based systems. Topics include virtualization, containerization, microservices, serverless computing, and distributed databases. Students deploy projects on AWS and Azure.", Credits = 3, Department = "Computer Science", Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Tech Center 215", Instructor = _instructors[5], MaxEnrollment = 40, CurrentEnrollment = 32 },

            // Mathematics
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Introduction to single-variable calculus covering limits, derivatives, and integrals. Applications to physics, biology, and economics are emphasized throughout the course.", Credits = 4, Department = "Mathematics", Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 101", Instructor = _instructors[1], IsFeatured = true, MaxEnrollment = 150, CurrentEnrollment = 130 },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications. Essential for students pursuing computer science, physics, or advanced mathematics.", Credits = 3, Department = "Mathematics", Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Math Building 203", Instructor = _instructors[1], MaxEnrollment = 80, CurrentEnrollment = 65 },
            new() { Id = 7, Code = "MATH 350", Title = "Probability and Statistics", Description = "Introduction to probability theory, random variables, distributions, hypothesis testing, and regression analysis. Applications to data science and real-world decision making.", Credits = 3, Department = "Mathematics", Schedule = "Mon/Wed 11:00 AM–12:20 PM", Location = "Math Building 105", Instructor = _instructors[1], MaxEnrollment = 70, CurrentEnrollment = 52 },

            // English
            new() { Id = 8, Code = "ENG 101", Title = "College Writing", Description = "Develop college-level writing skills through essays, research papers, and peer review. Covers argumentation, evidence-based writing, and MLA/APA citation styles.", Credits = 3, Department = "English", Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Humanities 301", Instructor = _instructors[2], MaxEnrollment = 30, CurrentEnrollment = 28 },
            new() { Id = 9, Code = "ENG 220", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present. Readings include works by Hawthorne, Whitman, Twain, Fitzgerald, Morrison, and contemporary authors.", Credits = 3, Department = "English", Schedule = "Tue/Thu 2:00–3:20 PM", Location = "Humanities 205", Instructor = _instructors[2], IsFeatured = true, MaxEnrollment = 35, CurrentEnrollment = 29 },

            // Physics
            new() { Id = 10, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Covers Newton's laws, conservation of energy and momentum, rotational motion, and an introduction to thermodynamics. Includes weekly lab sessions.", Credits = 4, Department = "Physics", Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:50 PM", Location = "Physics Lab 101", Instructor = _instructors[3], MaxEnrollment = 90, CurrentEnrollment = 78 },
            new() { Id = 11, Code = "PHYS 301", Title = "Quantum Mechanics", Description = "Introduction to quantum theory including wave-particle duality, Schrödinger equation, quantum states, measurement, and applications to atomic and molecular systems.", Credits = 3, Department = "Physics", Schedule = "Tue/Thu 11:00 AM–12:20 PM", Location = "Physics Lab 210", Instructor = _instructors[3], MaxEnrollment = 30, CurrentEnrollment = 22 },

            // History
            new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of world civilizations from prehistory through the Renaissance. Examines political, economic, social, and cultural developments across Asia, Africa, Europe, and the Americas.", Credits = 3, Department = "History", Schedule = "Mon/Wed/Fri 2:00–2:50 PM", Location = "Social Science 401", Instructor = _instructors[4], MaxEnrollment = 100, CurrentEnrollment = 85 },
            new() { Id = 13, Code = "HIST 310", Title = "Modern East Asia", Description = "Study of East Asian history from the 19th century to the present, focusing on China, Japan, and Korea. Topics include imperialism, revolution, war, economic development, and cultural change.", Credits = 3, Department = "History", Schedule = "Tue/Thu 3:30–4:50 PM", Location = "Social Science 305", Instructor = _instructors[4], IsFeatured = true, MaxEnrollment = 40, CurrentEnrollment = 33 },

            // Biology
            new() { Id = 14, Code = "BIO 101", Title = "Introduction to Biology", Description = "Fundamentals of biological science covering cell biology, genetics, evolution, ecology, and human biology. Includes weekly laboratory exercises to develop scientific observation and experimentation skills.", Credits = 4, Department = "Biology", Schedule = "Mon/Wed 9:00–10:20 AM + Fri Lab 1:00–3:50 PM", Location = "Life Sciences 101", Instructor = _instructors[6], MaxEnrollment = 100, CurrentEnrollment = 88 },
            new() { Id = 15, Code = "BIO 320", Title = "Molecular Genetics", Description = "Advanced study of gene structure, function, and regulation at the molecular level. Topics include DNA replication, transcription, translation, gene expression, and modern genetic engineering techniques.", Credits = 3, Department = "Biology", Schedule = "Tue/Thu 10:30 AM–12:00 PM", Location = "Life Sciences 310", Instructor = _instructors[6], IsFeatured = true, MaxEnrollment = 35, CurrentEnrollment = 30 },

            // Chemistry
            new() { Id = 16, Code = "CHEM 101", Title = "General Chemistry I", Description = "Introduction to chemical principles including atomic structure, bonding, stoichiometry, thermochemistry, and gas laws. Laboratory component reinforces lecture concepts with hands-on experiments.", Credits = 4, Department = "Chemistry", Schedule = "Mon/Wed/Fri 10:00–10:50 AM + Tue Lab 1:00–3:50 PM", Location = "Chemistry Building 101", Instructor = _instructors[7], MaxEnrollment = 90, CurrentEnrollment = 75 },
            new() { Id = 17, Code = "CHEM 301", Title = "Organic Chemistry I", Description = "Structure, nomenclature, and reactivity of organic compounds. Covers alkanes, alkenes, alkynes, stereochemistry, and substitution/elimination reactions. Essential for pre-med and chemistry majors.", Credits = 4, Department = "Chemistry", Schedule = "Tue/Thu 9:00–10:20 AM + Wed Lab 2:00–4:50 PM", Location = "Chemistry Building 205", Instructor = _instructors[7], MaxEnrollment = 50, CurrentEnrollment = 42 },
        };
    }

    public List<string> GetDepartments()
    {
        return _courses.Select(c => c.Department).Distinct().OrderBy(d => d).ToList();
    }

    public List<Course> GetCourses(string? department = null, string? searchTerm = null, int? credits = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(department))
            query = query.Where(c => c.Department == department);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (credits.HasValue)
            query = query.Where(c => c.Credits == credits.Value);

        return query.OrderBy(c => c.Department).ThenBy(c => c.Code).ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<int> GetAvailableCreditValues() => _courses.Select(c => c.Credits).Distinct().OrderBy(c => c).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real application, this would persist the request to a database
        var course = GetCourse(request.CourseId);
        return course is not null && course.CurrentEnrollment < course.MaxEnrollment;
    }
}

