    [Parameter] public string? InitialDepartment { get; set; }

    private string SearchTerm { get; set; } = string.Empty;
    private string SelectedDepartment { get; set; } = string.Empty;
    private string SelectedCredits { get; set; } = string.Empty;

    protected override void OnParametersSet()
    {
        if (InitialDepartment is not null && SelectedDepartment != InitialDepartment)
        {
            SelectedDepartment = InitialDepartment;
        }
    }

    private async Task OnFilterChanged()
    {
        int? credits = int.TryParse(SelectedCredits, out var c) ? c : null;
        var dept = string.IsNullOrEmpty(SelectedDepartment) ? null : SelectedDepartment;
        var search = string.IsNullOrEmpty(SearchTerm) ? null : SearchTerm;
        await OnFiltersChanged.InvokeAsync((search, dept, credits));
    }

    private async Task ClearFilters()
    {
        SearchTerm = string.Empty;
        SelectedDepartment = string.Empty;
        SelectedCredits = string.Empty;
        await OnFiltersChanged.InvokeAsync((null, null, null));
    }
}
