<PageTitle>University Course Catalog</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">University Course Catalog</h1>
    <p class="lead text-muted">Explore our departments, discover courses, and submit your enrollment request.</p>
    <a href="catalog" class="btn btn-primary btn-lg me-2">Browse All Courses</a>
    <a href="enroll" class="btn btn-outline-primary btn-lg">Enroll Now</a>
</div>

<FeaturedCourses Courses="featuredCourses" />

<DepartmentLinks Departments="departments" />

@code {
    private List<Models.Course> featuredCourses = new();
    private List<string> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetDepartments();
    }
}

