@page "/courses/{Id:int}"
@using CourseCatalog.Services
@using CourseCatalog.Components.Shared
@inject CatalogService CatalogService

<PageTitle>@(course?.Title ?? "Course Not Found")</PageTitle>

@if (course is null)
{
    <div class="alert alert-warning">
        <h4>Course not found</h4>
        <p>The course you're looking for doesn't exist. <a href="catalog">Browse the catalog</a>.</p>
    </div>
}
else
{
    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="catalog?department=@Uri.EscapeDataString(course.Department)">@course.Department</a></li>
            <li class="breadcrumb-item active">@course.Code</li>
        </ol>
    </nav>

    <CourseInfo Course="course" />

    <InstructorBio Instructor="course.Instructor" />

    <div class="mt-4">
        @if (course.CurrentEnrollment < course.MaxEnrollment)
        {
            <a href="enroll?courseId=@course.Id" class="btn btn-primary btn-lg">Request Enrollment</a>
        }
        else
        {
            <button class="btn btn-secondary btn-lg" disabled>Course Full</button>
        }
        <a href="catalog" class="btn btn-outline-secondary btn-lg ms-2">Back to Catalog</a>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Models.Course? course;

    protected override void OnParametersSet()
    {
        course = CatalogService.GetCourse(Id);
    }
}

@page "/enroll"
@using CourseCatalog.Models
@using CourseCatalog.Services
@using CourseCatalog.Components.Shared
@inject CatalogService CatalogService
@inject NavigationManager Nav

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (submitted)
{
    <div class="alert @(success ? "alert-success" : "alert-danger")">
        @if (success)
        {
            <h4>✅ Request Submitted!</h4>
            <p>Your enrollment request has been received. You will be notified by email once it is processed.</p>
            <a href="catalog" class="btn btn-outline-success">Back to Catalog</a>
        }
        else
        {
            <h4>❌ Submission Failed</h4>
            <p>The selected course may be full or unavailable. Please try a different course.</p>
            <button class="btn btn-outline-danger" @onclick="Reset">Try Again</button>
        }
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <div class="card">
                <div class="card-body">
                    <EnrollmentForm AvailableCourses="courses"
                                    PreselectedCourseId="preselectedCourseId"
                                    OnSubmit="HandleSubmit" />
                </div>
            </div>
        </div>
        <div class="col-lg-4">
            <div class="card bg-light">
                <div class="card-body">
                    <h5>ℹ️ How It Works</h5>
                    <ol class="mb-0">
                        <li>Fill out the form with your details</li>
                        <li>Select the course you wish to enroll in</li>
                        <li>Submit your request</li>
                        <li>You'll receive a confirmation email within 2 business days</li>
                    </ol>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private List<Course> courses = new();
    private int? preselectedCourseId;
    private bool submitted;
    private bool success;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses();

        var uri = Nav.ToAbsoluteUri(Nav.Uri);
        if (Microsoft.AspNetCore.WebUtilities.QueryHelpers.ParseQuery(uri.Query).TryGetValue("courseId", out var idStr)
            && int.TryParse(idStr, out var id))
        {
            preselectedCourseId = id;
        }
    }

    private void HandleSubmit(EnrollmentRequest request)
    {
        success = CatalogService.SubmitEnrollmentRequest(request);
        submitted = true;
    }

    private void Reset()
    {
        submitted = false;
        success = false;
    }
}

